import type { BaseVariableConfig } from '../../Variable'

/**
 * Configuration type for label variables
 */
export type LabelVariableType<Type extends string = string> = BaseVariableConfig<Type>

/**
 * A Variable for a label field (display-only text).
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the label variable including:
 *   * **question** - Question text displayed to the user
 *   * And all other properties from the base Variable type
 */
export function LabelVariable(config: LabelVariableType) {
    return config
}
